class Updater : public QObject
{
    Q_OBJECT
    Q_PROPERTY(QPointF value READ value NOTIFY valueChanged)

public:
    Updater(QObject* parent = nullptr);
    ~Updater();

    QPointF value() const { return m_value; }

public slots:
    void start();
    void stop();

signals:
    void valueChanged();

private:
    QThread m_thread;
    QPointF m_value;
};

class Data : public QObject
{
    Q_OBJECT
    Q_PROPERTY(QPointF value READ value NOTIFY valueChanged)

public:
    Data(Updater* updater, QObject* parent = nullptr);
    ~Data();

    QPointF value() const { return m_value; }

public slots:
    void update();

signals:
    void valueChanged();

private:
    Updater* m_updater;
    QPointF m_value;
};
```

```
Updater::Updater(QObject* parent) : QObject(parent)
{
    moveToThread(&m_thread);
    connect(&m_thread, &QThread::started, this, &Updater::start);
    connect(&m_thread, &QThread::finished, this, &Updater::deleteLater);
    m_thread.start();
}

Updater::~Updater()
{
    m_thread.quit();
    m_thread.wait();
}

void Updater::start()
{
    while(true){
        // your code to update the value
        emit valueChanged();
    }
}

void Updater::stop()
{
    // your code to stop updating the value
